import { Ratelimit } from "@upstash/ratelimit";
import { Redis } from "@upstash/redis";

export default async function rateLimit({ url, identifier, maxRequests, window, prefix }: NodeInputs, { auth } : NodeScriptOptions) : NodeOutput  {
  const token = await auth.getKey();
  // Create a new ratelimiter, that allows X requests per X window
  const ratelimit = new Ratelimit({
    redis: new Redis({ token, url }),
    limiter: Ratelimit.slidingWindow(maxRequests, window),
    analytics: true,
    /**
     * Optional prefix for the keys used in redis. This is useful if you want to share a redis
     * instance with other applications and want to avoid key collisions. The default prefix is
     * "@upstash/ratelimit"
     */
    prefix: prefix || "@upstash/ratelimit",
  });

  // Use a constant string to limit all requests with a single ratelimit
  // Or use a userID, apiKey or ip address for individual limits.
  const rateLimitIdentifier = identifier || "api";
  const { success } = await ratelimit.limit(rateLimitIdentifier);

  return { success };
}

