const modelId = $inputs.model;
if (!modelId) return undefined;

try {
  const response = await fetch('https://openrouter.ai/api/v1/models', {
    headers: { 'Authorization': 'Bearer ' + ($flow.kbIntegrationKey) }
  });
  const data = await response.json();
  const models = data.data || [];
  const model = models.find(m => m.id === modelId);
  if (!model || !model.supported_parameters) return undefined;

  const paramDefs = {
    temperature: { title: 'Temperature', description: 'Controls randomness. 0 = deterministic, 2 = max creativity. Default: 1.0', type: 'number' },
    max_tokens: { title: 'Max Tokens', description: 'Maximum number of tokens to generate.', type: 'number' },
    top_p: { title: 'Top P', description: 'Nucleus sampling threshold. Default: 1.0', type: 'number' },
    top_k: { title: 'Top K', description: 'Limits token choices per step. 0 = disabled.', type: 'number' },
    frequency_penalty: { title: 'Frequency Penalty', description: 'Penalizes frequent tokens. Range: -2 to 2.', type: 'number' },
    presence_penalty: { title: 'Presence Penalty', description: 'Penalizes present tokens. Range: -2 to 2.', type: 'number' },
    repetition_penalty: { title: 'Repetition Penalty', description: 'Reduces repetition. Range: 0 to 2. Default: 1.0', type: 'number' },
    min_p: { title: 'Min P', description: 'Min probability threshold. Range: 0 to 1.', type: 'number' },
    top_a: { title: 'Top A', description: 'Dynamic top-p. Range: 0 to 1.', type: 'number' },
    seed: { title: 'Seed', description: 'For deterministic sampling.', type: 'number' },
    stop: { title: 'Stop Sequences', description: 'Sequences that stop generation.', type: 'array' },
    logprobs: { title: 'Log Probs', description: 'Return log probabilities.', type: 'boolean' },
    top_logprobs: { title: 'Top Log Probs', description: 'Number of top logprobs to return (0-20).', type: 'number' }
  };

  const properties = {};
  let idx = 0;
  for (const param of model.supported_parameters) {
    if (paramDefs[param]) {
      properties[param] = {
        ...paramDefs[param],
        buildship: { index: idx++, isScriptInput: true, readOnly: false }
      };
    }
  }

  return { type: 'object', properties, required: [] };
} catch (e) {
  return undefined;
}

