meta.description:
What we send:

{
  "step": "review",
  "prompt": "<dart code string>",
  "context": { "architect_output": "<JSON string>" }
}
What BuildShip needs to do with it: Construct an OpenRouter messages array like:

{
  "messages": [
    { "role": "system", "content": "<system instructions for review step>" },
    { "role": "user", "content": "<prompt + context combined into a user message>" }
  ]
}

condition_c372163c_7dbb_422a_800c_41defd.script:
export default async function({
    step,
    prompt,
    context
}: NodeInputs) {
    const systemInstructions = {
        review: "You are a Dart code reviewer. Analyze the provided code for best practices, potential issues, and improvements. Provide constructive feedback on code quality, performance, and maintainability."
    };

    const systemContent = systemInstructions[step] || "You are a helpful assistant.";

    let userContent = prompt;
    if (context && context.architect_output) {
        userContent += `\n\nContext: ${context.architect_output}`;
    }

    return {
        messages: [{
                role: "system",
                content: systemContent
            },
            {
                role: "user",
                content: userContent
            }
        ]
    };
}

