import axios from "axios";

export default async function openRouterDynamic(
  { model, messages, systemPrompt, stream, ..._params }: NodeInputs,
  { auth, logging }: NodeScriptOptions
) {
  const apiKey = await auth.getKey();

  if (!model) throw new Error("Model is required.");
  if (!messages) throw new Error("Messages input is required.");

  // Build messages array
  const chatMessages = [];

  if (systemPrompt && systemPrompt.trim().length > 0) {
    chatMessages.push({ role: "system", content: systemPrompt.trim() });
  }

  // Accept messages as string (single user message) or array (full conversation)
  if (typeof messages === "string") {
    chatMessages.push({ role: "user", content: messages });
  } else if (Array.isArray(messages)) {
    chatMessages.push(...messages);
  } else {
    throw new Error("Messages must be a string or an array of message objects.");
  }

  // Build request body with only defined dynamic params
  const body: Record<string, any> = {
    model,
    messages: chatMessages,
    stream: stream || false,
  };

  // Forward supported dynamic parameters (skip undefined/null)
  for (const [key, val] of Object.entries(_params)) {
    if (val !== undefined && val !== null && val !== "") {
      body[key] = val;
    }
  }

  logging.log("OpenRouter request:", JSON.stringify({ model, stream: body.stream, paramCount: Object.keys(_params).filter(k => _params[k] !== undefined).length }));

  try {
    const response = await axios({
      method: "POST",
      url: "https://openrouter.ai/api/v1/chat/completions",
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Content-Type": "application/json",
        "HTTP-Referer": "https://buildship.com",
        "X-Title": "BuildShip Workflow",
      },
      data: body,
      responseType: stream ? "stream" : "json",
    });

    if (stream) {
      // For streaming, collect and return the full response
      const chunks: string[] = [];
      let fullContent = "";
      const streamData = response.data;

      return new Promise((resolve, reject) => {
        streamData.on("data", (chunk: Buffer) => {
          const lines = chunk.toString().split("\n").filter((l: string) => l.trim().startsWith("data:"));
          for (const line of lines) {
            const data = line.replace("data: ", "").trim();
            if (data === "[DONE]") continue;
            try {
              const parsed = JSON.parse(data);
              const delta = parsed.choices?.[0]?.delta?.content;
              if (delta) fullContent += delta;
            } catch (e) { /* ignore parse errors on SSE comments */ }
          }
        });
        streamData.on("end", () => {
          resolve({
            content: fullContent,
            model: body.model,
            streamed: true,
          });
        });
        streamData.on("error", reject);
      });
    }

    const data = response.data;
    const choice = data.choices?.[0];

    return {
      content: choice?.message?.content || null,
      role: choice?.message?.role || "assistant",
      finishReason: choice?.finish_reason || null,
      model: data.model || model,
      id: data.id || null,
      usage: data.usage || null,
      toolCalls: choice?.message?.tool_calls || null,
      raw: data,
    };
  } catch (error) {
    if (error.response) {
      const errData = error.response.data;
      logging.error("OpenRouter API error:", JSON.stringify({ status: error.response.status, data: errData }));
      throw new Error(`OpenRouter API error (${error.response.status}): ${JSON.stringify(errData?.error?.message || errData)}`);
    }
    throw new Error(`OpenRouter request failed: ${error.message}`);
  }
}

