import { Firestore, FieldValue } from '@google-cloud/firestore';

export default async function incrementUsage({ projectId, collectionName, userId }) {
  if (!projectId) throw new Error('GCP Project ID is required');
  if (!collectionName) throw new Error('Collection Name is required');
  if (!userId) throw new Error('User ID is required');

  const db = new Firestore({ projectId });
  const col = db.collection(collectionName);
  const snap = await col.where('user_id', '==', userId).limit(1).get();

  if (snap.empty) {
    return { status: 'not_found', usage_count: 0 };
  }


  const doc = snap.docs[0];
  const data = doc.data();
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

  const isNewMonth = data.usage_month !== currentMonth;
  const updateFields = {
    usage_count: isNewMonth ? 1 : FieldValue.increment(1),
    usage_month: currentMonth
  };

  await doc.ref.update(updateFields);

  const newCount = isNewMonth ? 1 : (data.usage_count ?? 0) + 1;
  return { status: 'success', usage_count: newCount, usage_month: currentMonth };
}

